function AnvilFaceHardenerMaker.init() AnvilFaceHardenerMaker.ironStock=18; AnvilFaceHardenerMaker.bronzeStock=14; AnvilFaceHardenerMaker.woodStock=10; AnvilFaceHardenerMaker.leatherStock=8; AnvilFaceHardenerMaker.silverStock=8; AnvilFaceHardenerMaker.goldStock=6; AnvilFaceHardenerMaker.jewelStock=4; AnvilFaceHardenerMaker.pearlStock=4; AnvilFaceHardenerMaker.productStock={}; AnvilFaceHardenerMaker.buildings={}; AnvilFaceHardenerMaker.maker=nil; AnvilFaceHardenerMaker.activeMaking={}; AnvilFaceHardenerMaker.totalProducts=0; AnvilFaceHardenerMaker.dayTimer=0; print("[AnvilFaceHardenerMaker] Royal Anvil Face Hardener Maker System initialized (6 products, 4 buildings)") end
function AnvilFaceHardenerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnvilFaceHardenerMaker.maker={name=n or ("Utrjevalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Utrjevalec najet: %s (spretnost: %d)",AnvilFaceHardenerMaker.maker.name,s),"success") end; return true end
function AnvilFaceHardenerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnvilFaceHardenerMaker.build(id) local ok,e=AnvilFaceHardenerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnvilFaceHardenerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnvilFaceHardenerMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnvilFaceHardenerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnvilFaceHardenerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AnvilFaceHardenerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AnvilFaceHardenerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AnvilFaceHardenerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AnvilFaceHardenerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AnvilFaceHardenerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnvilFaceHardenerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnvilFaceHardenerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnvilFaceHardenerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnvilFaceHardenerMaker.buildings==0 then return false,"Potrebna utrjevalna delavnica" end; if not AnvilFaceHardenerMaker.maker then return false,"Potreben utrjevalec" end; return true end
function AnvilFaceHardenerMaker.make(pt,qty) qty=qty or 1; local ok,e=AnvilFaceHardenerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AnvilFaceHardenerMaker.ironStock=AnvilFaceHardenerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AnvilFaceHardenerMaker.bronzeStock=AnvilFaceHardenerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AnvilFaceHardenerMaker.woodStock=AnvilFaceHardenerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AnvilFaceHardenerMaker.leatherStock=AnvilFaceHardenerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AnvilFaceHardenerMaker.silverStock=AnvilFaceHardenerMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnvilFaceHardenerMaker.goldStock=AnvilFaceHardenerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnvilFaceHardenerMaker.jewelStock=AnvilFaceHardenerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnvilFaceHardenerMaker.pearlStock=AnvilFaceHardenerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnvilFaceHardenerMaker.maker then t=math.max(1,t-math.floor(AnvilFaceHardenerMaker.maker.skill/13)) end; table.insert(AnvilFaceHardenerMaker.activeMaking,{id="anvilfacehardener_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnvilFaceHardenerMaker.completeMaking(m) local q=1.0+(AnvilFaceHardenerMaker.getQualityBonus()/100); if AnvilFaceHardenerMaker.maker then q=q+(AnvilFaceHardenerMaker.maker.skill/140) end; q=math.min(2.5,q); AnvilFaceHardenerMaker.productStock[m.productType]=(AnvilFaceHardenerMaker.productStock[m.productType] or 0)+m.quantity; AnvilFaceHardenerMaker.totalProducts=AnvilFaceHardenerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnvilFaceHardenerMaker.maker then AnvilFaceHardenerMaker.maker.itemsMade=AnvilFaceHardenerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnvilFaceHardenerMaker.maker.skill=math.min(100,AnvilFaceHardenerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Utrjevalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"anvilfacehardener.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AnvilFaceHardenerMaker.update(dt) if not _G.state then return end; AnvilFaceHardenerMaker.dayTimer=AnvilFaceHardenerMaker.dayTimer+dt; if AnvilFaceHardenerMaker.dayTimer>=30 then AnvilFaceHardenerMaker.dayTimer=0; for i=#AnvilFaceHardenerMaker.activeMaking,1,-1 do local m=AnvilFaceHardenerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnvilFaceHardenerMaker.completeMaking(m); table.remove(AnvilFaceHardenerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnvilFaceHardenerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnvilFaceHardenerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnvilFaceHardenerMaker.getStats() return {ironStock=AnvilFaceHardenerMaker.ironStock,bronzeStock=AnvilFaceHardenerMaker.bronzeStock,woodStock=AnvilFaceHardenerMaker.woodStock,leatherStock=AnvilFaceHardenerMaker.leatherStock,silverStock=AnvilFaceHardenerMaker.silverStock,goldStock=AnvilFaceHardenerMaker.goldStock,jewelStock=AnvilFaceHardenerMaker.jewelStock,pearlStock=AnvilFaceHardenerMaker.pearlStock,productStock=AnvilFaceHardenerMaker.productStock,numBuildings=#AnvilFaceHardenerMaker.buildings,hasMaker=AnvilFaceHardenerMaker.maker~=nil,makerName=AnvilFaceHardenerMaker.maker and AnvilFaceHardenerMaker.maker.name or "—",makerSkill=AnvilFaceHardenerMaker.maker and AnvilFaceHardenerMaker.maker.skill or 0,activeMaking=#AnvilFaceHardenerMaker.activeMaking,totalProducts=AnvilFaceHardenerMaker.totalProducts} end
